<?php
declare(strict_types=1);
namespace Vendor\ContaoIssueServiceBundle\Application;
use Doctrine\DBAL\Connection;
use Symfony\Component\Mailer\MailerInterface;
use Symfony\Component\Mime\Email;
use Symfony\Component\Uid\Uuid;
final class NotificationService { public function __construct(private readonly Connection $db,private readonly SettingsService $settings,private readonly MailerInterface $mailer,private readonly string $fromAddress){} public function enqueue(int $issueId,string $template):void{$issue=$this->db->fetchAssociative('SELECT i.ticket_number,i.title,s.notification_recipients FROM tl_issue i JOIN tl_issue_service s ON s.id=i.service_id WHERE i.id=:id',['id'=>$issueId]);if(false===$issue)return;$recipients=array_unique(array_filter(array_merge($this->settings->json('mail_recipients',[]),json_decode((string)$issue['notification_recipients'],true)?:[])));$event=Uuid::v7()->toBinary();$now=(new \DateTimeImmutable())->format('Y-m-d H:i:s');foreach($recipients as $r){if(!filter_var($r,FILTER_VALIDATE_EMAIL))continue;$this->db->insert('tl_issue_notification',['event_uuid'=>$event,'issue_id'=>$issueId,'recipient'=>$r,'template_key'=>$template,'status'=>'pending','attempt_count'=>0,'created_at'=>$now]);}} public function dispatchPending(int $limit=50):int{$rows=$this->db->fetchAllAssociative("SELECT n.*,i.ticket_number,i.title FROM tl_issue_notification n JOIN tl_issue i ON i.id=n.issue_id WHERE n.status IN ('pending','retry') AND (n.next_attempt_at IS NULL OR n.next_attempt_at<=NOW()) ORDER BY n.id LIMIT ".(int)$limit);$sent=0;foreach($rows as $r){try{$this->mailer->send((new Email())->from($this->fromAddress)->to($r['recipient'])->subject('['.$r['ticket_number'].'] '.$r['title'])->text('Im Vorgang '.$r['ticket_number'].' liegt eine neue Aktivität vor.'));$this->db->update('tl_issue_notification',['status'=>'sent','sent_at'=>(new \DateTimeImmutable())->format('Y-m-d H:i:s'),'last_error'=>null],['id'=>$r['id']]);$sent++;}catch(\Throwable $e){$attempt=(int)$r['attempt_count']+1;$this->db->update('tl_issue_notification',['status'=>'retry','attempt_count'=>$attempt,'last_error'=>substr($e->getMessage(),0,1000),'next_attempt_at'=>(new \DateTimeImmutable('+'.min(1440,2**min($attempt,10)).' minutes'))->format('Y-m-d H:i:s')],['id'=>$r['id']]);}}return $sent;} }
